 @AfterAll void evidence()throws Exception{Path dir=Path.of("../docs/qa/evidence");Files.createDirectories(dir);Files.writeString(dir.resolve("lifecycle.json"),json.writeValueAsString(Map.of("steps",steps,"propertyId",property,"contractId",contract,"invoiceId",invoice,"schema",f.dataSource.getUrl().replaceAll("\\?.*",""),"browserRun",Boolean.getBoolean("prompt11.browser"))));if(Boolean.getBoolean("prompt11.browser")&&!steps.isEmpty()&&steps.getLast().startsWith("38-40")){String run=UUID.randomUUID().toString();var data=new LinkedHashMap<String,Object>(Map.of("runId",run,"api",base(),"tenantEmail",tenantEmail,"password",password,"ownerEmail","p03-1@test.invalid","managerEmail","p03-2@test.invalid","accountantEmail","p03-3@test.invalid","technicianEmail","p03-6@test.invalid"));data.put("propertyId",property);data.put("roomId",room);data.put("contractId",contract);data.put("invoiceId",invoice);data.put("taskId",task);Files.writeString(Path.of("D:/DATN/prompt11-browser-ready.json"),json.writeValueAsString(data));long until=System.nanoTime()+Duration.ofMinutes(8).toNanos();Path done=Path.of("D:/DATN/prompt11-browser-complete.json");while(System.nanoTime()<until){if(Files.exists(done)){var result=json.readTree(Files.readString(done));if(run.equals(result.path("runId").asText())){assertThat(result.path("status").asText()).isEqualTo("PASS");return;}}Thread.sleep(200);}throw new AssertionError("Browser evidence timed out");}}
